export function searchFood(query: string): FoodItem[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return [];
  return FOOD_DATABASE
    .filter((f) => f.name.toLowerCase().includes(needle))
    .slice(0, 10);
}
